package com.sarathi.api.booking;
import com.sarathi.api.common.ApiException;
import com.sarathi.api.security.UserPrincipal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Map;
import java.util.UUID;
@Service
public class BookingService {
 private final JdbcTemplate db;
 public BookingService(JdbcTemplate db){this.db=db;}
 @Transactional public Map<String,Object> create(UserPrincipal user,BookingRequest r){
  if(!user.role().equals("FARMER")&&!user.role().equals("ADMIN"))throw ApiException.forbidden("Only a farmer can request equipment.");
  if(!r.endDate().isAfter(r.startDate()))throw ApiException.badRequest("End date must be after start date.");
  if((r.farmLatitude()==null)!=(r.farmLongitude()==null))throw ApiException.badRequest("Farm coordinates must be supplied together.");
  if(r.farmLatitude()!=null&&(r.farmLatitude() < -90||r.farmLatitude()>90||r.farmLongitude() < -180||r.farmLongitude()>180))throw ApiException.badRequest("Farm coordinates are invalid.");
  if(r.idempotencyKey()!=null){var existing=db.query("SELECT * FROM bookings WHERE renter_id=? AND idempotency_key=?",(rs,n)->new org.springframework.jdbc.core.ColumnMapRowMapper().mapRow(rs,n),user.id(),r.idempotencyKey());if(!existing.isEmpty())return Map.of("booking",existing.get(0));}
  var machines=db.query("SELECT * FROM equipment WHERE id=? FOR UPDATE",(rs,n)->new org.springframework.jdbc.core.ColumnMapRowMapper().mapRow(rs,n),r.equipmentId());if(machines.isEmpty())throw ApiException.notFound("Equipment not found.");Map<String,Object> e=machines.get(0);
  if(!"AVAILABLE".equals(e.get("status")))throw ApiException.conflict("This equipment is not currently available.");if(user.id().equals(e.get("owner_id")))throw ApiException.badRequest("You cannot book your own equipment.");
  var overlaps=db.queryForList("SELECT id FROM bookings WHERE equipment_id=? AND status IN ('PENDING','CONFIRMED','IN_PROGRESS') AND start_date<? AND end_date>? LIMIT 1",r.equipmentId(),r.endDate(),r.startDate());if(!overlaps.isEmpty())throw ApiException.conflict("Those dates overlap another active booking. Choose different dates.");
  long days=ChronoUnit.DAYS.between(r.startDate(),r.endDate());long daily=((Number)e.get("price_per_day_paise")).longValue();Object perAcre=e.get("price_per_acre_paise");long rental=(perAcre!=null&&r.acres()!=null)?Math.round(((Number)perAcre).doubleValue()*r.acres()):daily*days;
  long operatorFee=0;if(r.operatorId()!=null&&!r.operatorId().isBlank()){var op=db.queryForList("SELECT p.daily_rate_paise FROM operator_profiles p JOIN users u ON u.id=p.user_id WHERE p.user_id=? AND p.available=1 AND u.active=1 AND JSON_CONTAINS(p.skills,JSON_QUOTE(?))=1",r.operatorId(),e.get("type"));if(op.isEmpty())throw ApiException.conflict("That operator is unavailable or not qualified for this equipment.");var busy=db.queryForList("SELECT id FROM bookings WHERE operator_id=? AND status IN ('PENDING','CONFIRMED','IN_PROGRESS') AND start_date<? AND end_date>? LIMIT 1",r.operatorId(),r.endDate(),r.startDate());if(!busy.isEmpty())throw ApiException.conflict("That operator already has a booking during those dates.");operatorFee=((Number)op.get(0).get("daily_rate_paise")).longValue()*days;}
  long transport=((Number)e.get("transport_fee_paise")).longValue(),total=rental+operatorFee+transport;String id=UUID.randomUUID().toString();
  db.update("INSERT INTO bookings(id,equipment_id,renter_id,operator_id,start_date,end_date,acres,status,daily_rate_paise,rental_amount_paise,operator_fee_paise,transport_fee_paise,total_paise,renter_note,idempotency_key,farm_village,farm_district,farm_latitude,farm_longitude) VALUES(?,?,?,?,?,?,?,'PENDING',?,?,?,?,?,?,?,?,?,?,?)",id,r.equipmentId(),user.id(),blankToNull(r.operatorId()),r.startDate(),r.endDate(),r.acres(),daily,rental,operatorFee,transport,total,r.note()==null?"":r.note(),r.idempotencyKey(),r.farmVillage(),r.farmDistrict(),r.farmLatitude(),r.farmLongitude());
  audit(user.id(),"BOOKING_REQUESTED","BOOKING",id);return Map.of("booking",db.queryForMap("SELECT * FROM bookings WHERE id=?",id));
 }
 @Transactional public Map<String,Object> decision(UserPrincipal user,String id,String decision,String note){var row=bookingForUpdate(id);if(row==null||!user.id().equals(row.get("owner_id"))&&!user.role().equals("ADMIN"))throw ApiException.notFound("Booking not found.");if(!"PENDING".equals(row.get("status")))throw ApiException.conflict("Only pending requests can be accepted or declined.");if(!decision.equals("CONFIRMED")&&!decision.equals("REJECTED"))throw ApiException.badRequest("Decision must be CONFIRMED or REJECTED.");db.update("UPDATE bookings SET status=?,owner_note=? WHERE id=?",decision,note==null?"":note,id);if(decision.equals("CONFIRMED"))db.update("INSERT INTO payments(id,booking_id,payer_id,payee_id,rental_amount_paise,transport_paise,operator_paise) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID().toString(),id,row.get("renter_id"),row.get("owner_id"),row.get("rental_amount_paise"),row.get("transport_fee_paise"),row.get("operator_fee_paise"));audit(user.id(),"BOOKING_"+decision,"BOOKING",id);return Map.of("booking",db.queryForMap("SELECT * FROM bookings WHERE id=?",id));}
 @Transactional public Map<String,Object> cancel(UserPrincipal user,String id){var row=bookingForUpdate(id);if(row==null||!user.id().equals(row.get("renter_id"))&&!user.id().equals(row.get("owner_id"))&&!user.role().equals("ADMIN"))throw ApiException.notFound("Booking not found.");String status=String.valueOf(row.get("status"));if(!status.equals("PENDING")&&!status.equals("CONFIRMED"))throw ApiException.conflict("This booking can no longer be cancelled.");db.update("UPDATE bookings SET status='CANCELLED' WHERE id=?",id);db.update("UPDATE payments SET status='FAILED' WHERE booking_id=? AND status='PENDING'",id);audit(user.id(),"BOOKING_CANCELLED","BOOKING",id);return Map.of("booking",db.queryForMap("SELECT * FROM bookings WHERE id=?",id));}
 @Transactional public Map<String,Object> assign(UserPrincipal user,String id,String operatorId){var row=bookingForUpdate(id);if(row==null||!user.id().equals(row.get("owner_id"))&&!user.role().equals("ADMIN"))throw ApiException.notFound("Booking not found.");if(!"CONFIRMED".equals(row.get("status")))throw ApiException.conflict("Assign an operator after confirming the booking.");var op=db.queryForList("SELECT p.daily_rate_paise FROM operator_profiles p WHERE p.user_id=? AND p.available=1 AND JSON_CONTAINS(p.skills,JSON_QUOTE(?))=1",operatorId,row.get("equipment_type"));if(op.isEmpty())throw ApiException.conflict("Operator is unavailable or not qualified for this machine.");if(!db.queryForList("SELECT id FROM payments WHERE booking_id=? AND status<>'PENDING'",id).isEmpty())throw ApiException.conflict("A settled payment cannot be changed; resolve the payment before assigning an operator.");var busy=db.queryForList("SELECT id FROM bookings WHERE operator_id=? AND id<>? AND status IN ('PENDING','CONFIRMED','IN_PROGRESS') AND start_date<? AND end_date>? LIMIT 1",operatorId,id,row.get("end_date"),row.get("start_date"));if(!busy.isEmpty())throw ApiException.conflict("Operator already has an overlapping booking.");long days=ChronoUnit.DAYS.between(((java.sql.Date)row.get("start_date")).toLocalDate(),((java.sql.Date)row.get("end_date")).toLocalDate());long operatorFee=((Number)op.get(0).get("daily_rate_paise")).longValue()*days;db.update("UPDATE bookings SET operator_id=?,operator_fee_paise=?,total_paise=total_paise+? WHERE id=?",operatorId,operatorFee,operatorFee,id);db.update("UPDATE payments SET operator_paise=? WHERE booking_id=? AND status='PENDING'",operatorFee,id);audit(user.id(),"OPERATOR_ASSIGNED","BOOKING",id);return Map.of("booking",db.queryForMap("SELECT * FROM bookings WHERE id=?",id));}
 @Transactional public Map<String,Object> complete(UserPrincipal user,String id){var row=bookingForUpdate(id);if(row==null||!user.id().equals(row.get("owner_id"))&&!user.role().equals("ADMIN"))throw ApiException.notFound("Booking not found.");if(!"CONFIRMED".equals(row.get("status")))throw ApiException.conflict("Only confirmed bookings can be completed.");if(((java.sql.Date)row.get("end_date")).toLocalDate().isAfter(LocalDate.now()))throw ApiException.conflict("This booking has not ended yet.");db.update("UPDATE bookings SET status='COMPLETED' WHERE id=?",id);return Map.of("booking",db.queryForMap("SELECT * FROM bookings WHERE id=?",id));}
 public java.util.List<Map<String,Object>> list(String userId){return db.queryForList("SELECT b.*,e.name AS equipment_name,e.type AS equipment_type,e.owner_id,u.full_name AS renter_name,op.full_name AS operator_name FROM bookings b JOIN equipment e ON e.id=b.equipment_id JOIN users u ON u.id=b.renter_id LEFT JOIN users op ON op.id=b.operator_id WHERE b.renter_id=? OR e.owner_id=? ORDER BY b.start_date DESC,b.created_at DESC",userId,userId);}
 private Map<String,Object> bookingForUpdate(String id){var rows=db.query("SELECT b.*,e.owner_id,e.type AS equipment_type FROM bookings b JOIN equipment e ON e.id=b.equipment_id WHERE b.id=? FOR UPDATE",(rs,n)->new org.springframework.jdbc.core.ColumnMapRowMapper().mapRow(rs,n),id);return rows.isEmpty()?null:rows.get(0);}
 private String blankToNull(String s){return s==null||s.isBlank()?null:s;}
 private void audit(String actor,String action,String type,String entity){db.update("INSERT INTO audit_events(actor_id,action,entity_type,entity_id,metadata) VALUES(?,?,?,?,JSON_OBJECT())",actor,action,type,entity);}
}
